// Extract request data
const userMessage = $json.message || '';
const conversationHistory = $json.history || [];
let sessionId = $json.sessionId || null;
let sessionState = $json.state || null;

// Generate session ID if new conversation
if (!sessionId) {
  sessionId = `ba-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

// Initialize session state if new
if (!sessionState) {
  sessionState = {
    step: 0,
    systemBrief: null,
    projectName: null,
    projectType: null,
    platforms: [],
    githubRepo: null,
    targetBranch: 'main',
    coreFeatures: [],
    constraints: [],
    nfrs: [], // Non-functional requirements
    requirementsComplete: false,
    projectId: null
  };
}

// Add user message to history
conversationHistory.push({
  role: 'user',
  content: userMessage,
  timestamp: new Date().toISOString()
});

return {
  json: {
    userMessage,
    conversationHistory,
    sessionId,
    sessionState
  }
};

// Parse LLM response
const llmResponse = JSON.parse($json.choices[0].message.content);
const initData = $('Initialize Session').first().json;
const sessionState = initData.sessionState;
const sessionId = initData.sessionId;
const conversationHistory = initData.conversationHistory;

// Update session state with extracted info
const extractedInfo = llmResponse.extractedInfo || {};
const updatedState = {
  ...sessionState,
  systemBrief: extractedInfo.systemBrief || sessionState.systemBrief,
  projectName: extractedInfo.projectName || sessionState.projectName,
  projectType: extractedInfo.projectType || sessionState.projectType,
  platforms: extractedInfo.platforms || sessionState.platforms,
  coreFeatures: extractedInfo.coreFeatures || sessionState.coreFeatures,
  constraints: extractedInfo.constraints || sessionState.constraints,
  nfrs: extractedInfo.nfrs || sessionState.nfrs,
  githubRepo: extractedInfo.githubRepo || sessionState.githubRepo,
  targetBranch: extractedInfo.targetBranch || sessionState.targetBranch,
  requirementsComplete: llmResponse.readyToGenerate || false,
  step: sessionState.step + 1
};

// Add assistant message to history
conversationHistory.push({
  role: 'assistant',
  content: llmResponse.assistantMessage,
  timestamp: new Date().toISOString()
});

return {
  json: {
    assistantMessage: llmResponse.assistantMessage,
    sessionId: sessionId,
    sessionState: updatedState,
    conversationHistory: conversationHistory,
    requirementsComplete: updatedState.requirementsComplete,
    extractedInfo: extractedInfo
  }
};

// Create functional requirements records
const projectId = $json.id;
const parseData = $('Parse LLM & Update State').first().json;
const sessionState = parseData.sessionState;
const requirements = [];

// Core features as functional requirements
if (sessionState.coreFeatures && sessionState.coreFeatures.length > 0) {
  sessionState.coreFeatures.forEach((feature, idx) => {
    requirements.push({
      project_id: projectId,
      requirement_type: 'functional',
      category: 'core_feature',
      priority: idx < 3 ? 'critical' : 'high',
      description: feature,
      source: 'system_brief',
      created_by: 'business-analyst'
    });
  });
}

// Constraints
if (sessionState.constraints && sessionState.constraints.length > 0) {
  sessionState.constraints.forEach(constraint => {
    requirements.push({
      project_id: projectId,
      requirement_type: 'constraint',
      category: 'business',
      priority: 'high',
      description: constraint,
      source: 'system_brief',
      created_by: 'business-analyst'
    });
  });
}

// Non-functional requirements
if (sessionState.nfrs && sessionState.nfrs.length > 0) {
  sessionState.nfrs.forEach(nfr => {
    requirements.push({
      project_id: projectId,
      requirement_type: 'non_functional',
      category: 'quality',
      priority: 'medium',
      description: nfr,
      source: 'system_brief',
      created_by: 'business-analyst'
    });
  });
}

return requirements.map(req => ({ json: req }));

const projectData = $('Create Project').first().json;
const projectId = projectData.id;
const projectName = projectData.project_name;
const parseData = $('Parse LLM & Update State').first().json;
const sessionId = parseData.sessionId;

return {
  json: {
    assistantMessage: `✅ Requirements gathering complete!

**Project Created**: ${projectName}
**Project ID**: ${projectId}

I've captured all your requirements and triggered the PRD Generator workflow.

The following expert consultations will now take place:
1. Compliance & Risk Assessor
2. Business Architect
3. Experience Design Optimizer
4. Technology CTO
5. Application Architect
6. Solution Architect (PRD-to-OAM)
7. Infrastructure Reviewer

You can monitor progress in the database or n8n execution logs.

Would you like to:
- Start another project
- View project status
- Exit`,
    sessionId,
    sessionState: parseData.sessionState,
    conversationHistory: parseData.conversationHistory,
    complete: true,
    projectId,
    projectName
  }
};

const sessionId = $json.sessionId;
const assistantMessage = $json.assistantMessage;
const sessionState = $json.sessionState;
const conversationHistory = $json.conversationHistory;

return {
  json: {
    assistantMessage,
    sessionId,
    sessionState,
    conversationHistory,
    complete: false
  }
};
